quests[85531] = { id = 85531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earth-Encrusted Gem", objectives = "The work of the Severed Threads proceeds apace. As such, our patrons have decided to reward your continued dedication.\n\nNow take this and begone. You're drawing suspicious eyes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
