quests[85538] = { id = 85538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shinies", objectives = "So helpful! Kobolds thank you. Earthen thank you. The Assembly thanks you! \n\nCandle for you! No better reward than that!\n\nNo, this candle not made from earwax. Made from beeswax! Smells so nice! You like nice smells, yes? If not, might want to step away from me, ha ha ha. Sorry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
