quests[85773] = { id = 85773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits for Hire" }
quests[85780] = { id = 85780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Where We Want Him", description = "Gallywix is down, but he ain't out. \n\nThe Gallagio is built like a fortress. If we want to keep him from threatening Undermine, or Azeroth, we gotta figure out how to get him outta there. Meet me and the other bosses back at the Incontinental Hotel.", completion = "We got the people of Undermine to thank for the opportunity to finally put Gallywix outta business for good.\n\nI ain't gonna waste it.", objectives = "Return to the Incontinental Hotel and speak with Gazlowe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85797] = { id = 85797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knife Fight" }
quests[85804] = { id = 85804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Parent Trap", description = "I'm happy to help in any way that I can.\n\nTo find Alleria, you must fly far north from here. She's hunting a new Shadowguard lieutenant in the hope of extracting information from him.\n\nLast I heard, she was on the outskirts of a place called the Fracture of Laacuna.", progress = "It is good to see both of you, especially my beautiful son.", completion = "My sister's vision must not come to pass!\n\n<Alleria seems frustrated.>\n\nI wish I could return, but that's simply not possible. There are things I can do here, however, and you two can help while we discuss the matter.", objectives = "Locate Alleria Windrunner at the Fracture of Laacuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85805] = { id = 85805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Cartels of Undermine", description = "Thanks for the hard work there, pal!\n\nWe've got some supplies prepped for you in the hotel. Come grab 'em from Smaks Topskimmer.", completion = "Here you go!", objectives = "Speak with Smaks Topskimmer in the Incontinental Hotel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85806] = { id = 85806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exalted with the Bilgewater Cartel", description = "You done good for the Bilgewater when they needed you. They won't forget that.\n\nTalk to Rocco Razzboom, he'll take care of ya.", completion = "Hey, this is for you.", objectives = "Speak with Rocco Razzboom at the Scrapshop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85807] = { id = 85807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exalted with the Blackwater Cartel", description = "The Blackwater Cartel is sailing smooth thanks to you. \n\nBoatswain Hardee has readied yer cut o' the plunder... that is to say, a respectable reward for your work.", completion = "Here's your cut, all above board.", objectives = "Speak with Boatswain Hardee at the Port Authority.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85808] = { id = 85808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exalted with Darkfuse Solutions", description = "Helpin' the Darkfuse ain't real popular, so they want to say thanks.\n\nThey gotta do it quiet like, so find Stitch Lowdown down in the sewers near Hovel Hill.", completion = "Here ya go, buddy. The help's been much appreciated.", objectives = "Speak with Sitch Lowdown in the sewers near Hovel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85809] = { id = 85809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exalted with the Steamwheedle Cartel", description = "The Steamwheedle Cartel wants to thank you for all the work you have done. \n\nObserve all safety protocols and see Lab Assistant Laszly for a reward.", completion = "We got somethin' for ya.", objectives = "Speak with Lab Assistant Laszly at Steamwheedle Laboratories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85810] = { id = 85810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exalted with Venture Co.", description = "Venture Co. is ready to pay dividends on all the work you've done for us.\n\nSpeak to Shredz the Scrapper for your reward.", completion = "You done good, pal. This is yours.", objectives = "Speak with Shredz the Scrapper at Venture Plaza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85811] = { id = 85811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrayir, Eyes of the Siren", description = "<The power of the storm has reformed Thrayir, Eyes of the Siren.  He awaits your acceptance.>", completion = "<Thrayir, Eyes of the Siren is ready to be harnessed.>", objectives = "Accept Thrayir, Eyes of the Siren.<The power of the storm has reformed Thrayir, Eyes of the Siren. He awaits your acceptance.>", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
