quests[85861] = { id = 85861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rug Monster!!!" }
quests[85862] = { id = 85862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Prince's Duty", description = "It's a big day, lad. We've got a parade of the troops, a visiting contingent from Ironforge, and I hear word your father--er, King Terenas--will be here to oversee everything.\n\nIt's days like today that you've been forged for, Arthas. Inspire your men. Prove yourself. \n\nWhip these troops into shape. No doubt Muradin has been itching for a brawl as well...", progress = "You are the best our kingdom has to offer, my son. Make us look good in front of our guests!", completion = "Well done, my son! I heard the soldiers from all the way over here--sounds like you gave them a lesson in humility. And the way you handled Muradin! But of course...\n\nYou were born for this.", objectives = "Spar with the troops in Lordaeron Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85863] = { id = 85863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Diving: Strange Storms" }
quests[85864] = { id = 85864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Diving: Fractured Laacunite" }
quests[85869] = { id = 85869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Many Jobs, Handle It!", description = "Shipping & Handling is tryin' out a new driver incentive program.\n\nDo some jobs and let's see how it goes eh?", progress = "Get back to work. Chop chop!", completion = "Great job out there. Here's the little extra you were promised--and a sweet tip from the boss lady.", objectives = "Complete 10 jobs for Shipping & Handling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85871] = { id = 85871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Blade's Forces", description = "Xal'atath brings with her an army of shadows and tricks. \n\nThey are nothing to our evolved forms! \n\nYou have been chosen--blessed with power by N'Zoth to serve as his champion. \n\nGo now and destroy them!", completion = "You are covered in the dust of shade like the blood of your enemies. Good.", objectives = "Defeat Xal'atath's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85873] = { id = 85873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Shadowy Invitation", sourceObjective = "Meet Locus-Walker in the Foundation Hall in Dornogal.", sourceObjectiveStatus = "unverified-source-field" }
quests[85874] = { id = 85874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldfish Rescue" }
quests[85875] = { id = 85875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascent of the Lich King", description = "<Icecrown lies before you. Waiting. \n\nFrostmourne bids you...\n\n... ascend.>", progress = "Arthas... my son.", completion = "Arthas... my son.\n\n<The crown weighs heavily upon your head.>\n\nYou shall learn in time...\n\n<The wind howls in your ears.>\n\n... that no king rules forever.", objectives = "Banish your memories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85876] = { id = 85876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading the Runes", description = "My curiosity is still not terminated, {name}. I would like to know more about these vrykul and why they came to this land.\n\n<Bargus's wiry brows knit together and his mustache bristles as he thinks.>\n\nThe tablets you found were by far the best source of information on the vrykul and whoever this \"Cyrce\" is. \n\nPerhaps there are additional tablets we missed?\n\nI have my ordained duties here, but please examine them and report back to me.", completion = "Fascinating. This \"galeorn\" you spoke of known as Thrayir may be worth further investigation.\n\nPerhaps we could uncover more about its significance along with those runekeys.\n\nIt seems my curiosity will not be terminated any time soon.", objectives = "Examine various Rune-Carved Tablets within the Forgotten Tomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85878] = { id = 85878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O' Thanagor", description = "You are the Lich King.\n\nThe whole of Azeroth is arrayed against you.\n\nShow them what it means to be king.", completion = "His reign was short, yet terrible.", objectives = "Defeat the usurpers atop Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85879] = { id = 85879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reduce, Reuse, Resell", description = "The guys over at S.C.R.A.P. could use some extra hands this week.\n\nYou want a piece of the pie, go find one of their reps named Carlo out in the field and see if he's got any work for you.\n\nBut if you find a piece of pie in any of those trash piles, don't, uh... Don't actually eat it. I hope that kinda goes without sayin'.", progress = "What d'you need, instructions?\n\nBig trash piles. Shovel. Get at it.", completion = "Yeah, Carlo had your name on some of the reports. You're efficient, I'll give ya that.\n\nHere's your cut of the resales.", objectives = "Complete 3 S.C.R.A.P. jobs in Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85884] = { id = 85884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Prince Who Would Be King", description = "Before I can tell you the story of the Lich King, we must learn about who he was before he put on his crown.\n\nBefore he pulled that cursed sword from the depths of Frostmourne Cavern. \n\nWe must talk about the prince who was promised the world, and the people who championed his cause. \n\nWe must start in Lordaeron, many years ago, on a day of pomp and circumstance.", completion = "<Cho has grown silent.>", objectives = "Hear the story of Prince Arthas Menethil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85885] = { id = 85885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: No King Rules Forever", description = "What makes a king? Is it his crown? Is it the sharpness of his sword? The coldness of his heart?\n\nPerhaps the undying servitude of his people?\n\nJust as it is difficult to say when a sapling becomes a tree, or a mountain becomes a hill, so too is it difficult to know when exactly Arthas Menethil passed into memory, and the Lich King was born.\n\nWhere do we draw the line between man and monster?", completion = "It is a heavy story, full of terrible deeds and unhappy endings.\n\nBut it is a story that must be told.", objectives = "Listen to the story of the Lich King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85888] = { id = 85888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artistic License" }
