quests[85913] = { id = 85913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Side Gig: Cleanup Detail", description = "We're looking for someone with a strong arm and stronger stomach to help deal with all the blood monsters popping up in the Ringing Deeps. The cleanup crews keep getting eaten and it's murder on our schedule.\n\nYou up for it?", completion = "Hey, not bad. Just try not to drip everywhere, okay?", objectives = "Kill blood monstrosities in the Writhing Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85914] = { id = 85914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Side Gig: Coolant Matters", description = "Sounds like the old Black Blood pipes in the Ringing Deeps are thawing out, but we haven't figured out a solution for all the goo they're packed with just yet. A few more budgetary meetings, though, and we're on it.\n\nIn the meantime, we earmarked a little cash for some temp help. That's you.\n\nGet out there and refreeze those pipes.", progress = "Try not to freeze any important bits off. We're not offering medical.", completion = "Cool.", objectives = "Ride Pamsy's Rocketboard in the Writhing Fields and freeze the pipeline.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
