quests[86319] = { id = 86319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Sky" }
quests[86320] = { id = 86320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bully For You!" }
quests[86321] = { id = 86321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Door to Door" }
quests[86327] = { id = 86327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tempest Fields", description = "Those Wastelanders have that broker's ribbon. We must get it back or you will never be able to reach Dimensius.\n\nThey are deliciously bloodthirsty. I think we should lure them to our cause. We need an army for the coming battle, and they have the numbers for that.\n\nThe void glass lies between their camp and us. That might provide a means to manipulate--speak with the Wastelanders.", completion = "The aura of Dimensius is tearing what's left of K'aresh apart. Soon he will draw in what remains of this little world.\n\nOur time to stop him grows shorter by the hour.", objectives = "Meet Xal'atath in the Tempest Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86332] = { id = 86332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distribution of Power", description = "My people need energy to live. We can harvest it from the pylons that were set out to collect it or hunt the energy scavengers that have siphoned off what is ours.\n\nLet's gather today's meager bounty of energy and then distribute it to my people. If we are to go to war together, it will help us both to know the character of your allies.", progress = "In the wastes of Merciless K'aresh, survival is all-important. We take what we need to ensure our future.", completion = "Your help does not go unnoticed. My people will live another day, and hopefully many more, thanks to the energy that's in those crates.", objectives = "Collect and distribute harvested energy in and around the Wastelander Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86339] = { id = 86339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oasis Overdrive", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86340] = { id = 86340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oasis Overdrive - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86341] = { id = 86341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oasis Overdrive - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86342] = { id = 86342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soaring over K'aresh", description = "We've been taking the k'arrocs out for flights outside of the Oasis. Perhaps you might be interested in riding one?", completion = "Splendid. It was enjoyable to watch both the k'arroc and yourself flying around out there. \n\nYou are quite the accomplished rider, {name}.", objectives = "Complete the \"Oasis Overdrive\" race.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86348] = { id = 86348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fox Bane", description = "You have done well with the slatebacks. Will you do as well with the thorntails?\n\nIf we are to improve their numbers, we will need some of their astral essence to produce new ones. Procure it for me.", progress = "Do you have the essences?", completion = "You are reliable, as always.", objectives = "Collect 10 Thorntail Essences while Phase Diving in Untethered Space on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86349] = { id = 86349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lapbug Essence Hunter", description = "Thorntails are known to hunt smaller creatures. If we are to increase their numbers, we should also increase the numbers of the lapbug population to compensate.\n\nGather some of their astral essence. You can use a phase conduit to get into Untethered Space.", progress = "How fare your efforts?", completion = "Excellent. I shall take it from here.", objectives = "Collect 10 Lapbug Essence in Untethered Space on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86350] = { id = 86350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eau de Foxy", description = "It's my favorite {race}! \n\nI've been sniffing around the Oasis and I've whipped up a batch of pheromones for those thorntails out there. Can you give them a good dose for me?\n\nLet Om'talad know when you're done--he was lookin' to do some testing too!", progress = "Did you apply the pheromones?", completion = "Ah, thank you for your assistance as always.", objectives = "Douse 8 Regal Thorntails in pheromones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86351] = { id = 86351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike a Pose", description = "We are running low on food for the thorntails. It is odd. They should be hunting for a larger portion of their food.\n\nCan you take some pictures of them for documentation purposes? Perhaps it will shed some light on the issue.", progress = "Have you taken the photos?", completion = "They are not hunting at all? This is unacceptable. We will need to find a solution posthaste.", objectives = "Document 10 Regal Thorntails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86352] = { id = 86352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting for a Good Author", description = "I am growing concerned that we may be in danger of overbalancing the ecosystem. We require a consultant. \n\nHave you read \"The Green Hills of Stranglethorn?\" I enjoyed it a great deal. The author appears to have turned from hunter to conservationist. Do not ask how I acquired this information. \n\nHowever, these are precisely the two skills I need. Retrieve him. Last I heard, he was in the Azure Span on the Dragon Isles. Use the portal to travel there.", completion = "If ye need my help, I need yours first.", objectives = "Look for Hemet Nesingwary in the Azure Span on the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86353] = { id = 86353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting the Young", description = "These gnolls have kidnapped children from Iskaara. I was going to sneak in and rescue them, but I could use some help. \n\nLet's split up. Two sets of eyes are better than one. If you spot any kids, tell 'em to gather at this spot. Tell them Hemet sent you. They know me.", progress = "We have to rescue those children! Who knows what the gnolls will do to them?", completion = "Good job, {name}. \n\nHave to say, I was pretty glad when you showed up. Don't know if I'd have been able to manage it myself.", objectives = "Rescue 6 Tuskarr Children in the Brakenhide Brambles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86354] = { id = 86354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Percussive Antidote", description = "These gnolls have been corrupting the land--growing too big and throwing off the ecosystem.\n\nWe need to stop them, and let this land recover from all that decay.", progress = "I don't relish the kills, but it has to be done.", completion = "We've cut out the corruption here. In time, the land'll recover.", objectives = "Slay gnolls and their minions in and around the Brakenhide Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86355] = { id = 86355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Using the Whole Animal", description = "K'aresh, eh? Sounds a bit like Netherstorm.\n\nI've been staying with the tuskarr for a while an' learning what I can from 'em. I was supposed to gather meat for the evening meal. If you can do that, I can start packing.", progress = "Make sure you harvest the whole animal. It'll go faster.", completion = "This ought to be enough tae feed the whole village!", objectives = "Collect 20 Bruffalon Meat nearby in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86356] = { id = 86356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sustainable Harvesting", description = "I'd like to repay the tuskarr's kindness for hosting me. They have some repairs that need doing.\n\nCan ye gather some wood for them? They can handle the repairs themselves--they just need a bit of help gatherin' the materials.", progress = "Did ye get the wood?", completion = "That ought to be plenty for every project they've got!", objectives = "Collect 12 Chopped Wood nearby in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86357] = { id = 86357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Noms", description = "The local ottuks have a symbiotic relationship with the tuskarr, and it's feeding time.\n\nCan ye put out some of the meat ye gathered for them?", progress = "Have ye fed those ottuks yet?", completion = "Good work! Full bellies ought to keep 'em happy enough.", objectives = "Place a Pile of Meat for the local ottuks just outside Iskaara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86358] = { id = 86358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Any Old Excuse", description = "This'll be the hardest task for ye yet.\n\nThe ottuk pups have to get acclimatized to touch. I... I need ye to go pet them. \n\nHard work, but it has to be done.", progress = "What do you think of the wee li'l pups?", completion = "I appreciate ye making such a big sacrifice, {name}. Your work here will never be forgotten.", objectives = "Pet 5 Ottuk Pups outside of Iskarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86359] = { id = 86359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to K'aresh", description = "Right then. I'm ready to go. How do we get there?", completion = "I have prepared myself for this moment, and yet I find myself... nervous. You may go, {name}. The author and I have much to discuss.", objectives = "Return to the Oasis on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86360] = { id = 86360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fantastic Ms. Fox", description = "The thorntails aren't hunting like they're supposed tae?\n\nVe'nari said that lapbugs aren't their normal prey. We'll need to teach the matriarch how to hunt them ourselves!", progress = "Is she hunting properly?", completion = "If you told a younger me I'd be teaching animals how to hunt, I'd have laughed you away.", objectives = "Teach the Thorntail Matriarch to hunt Lapbug Skitterers 10 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86361] = { id = 86361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Are You Kitting Me?", description = "We need to ensure that the thorntail kits' reflexes are sharp so they are effective hunters when they grow up.\n\nPlease take this ball and have a kit chase it. For scientific purposes, of course.", progress = "Has a kit been sufficiently trained?", completion = "Excellent--play can be as useful as training, on some occasions.", objectives = "Catch a ball 10 times while playing with your Thorntail Kit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86362] = { id = 86362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Does the Fox Dream?", description = "I'd like to get some medical data on how the thorntails are doing. Please gather some blood samples for me.\n\nUse these to tranquilize the creatures. There should be more than enough blood for sampling on the darts when you retrieve them.", progress = "Have you gathered the samples we need?", completion = "Excellent! Exactly what I needed. Perhaps you would like a full time position here?", objectives = "Collect 5 Blood Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86363] = { id = 86363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Better Part of Valorstones", description = "It's been many months since we arrived in Dornogal and there's still more to learn of Valorstones. It turns out they can be found beyond Azeroth! This discovery opens up entirely new avenues of research.\n\nWith new research comes a need for new supplies. Bring me some, and we'll help upgrade your gear to new heights.", progress = "There's no need to hurry. But if you wouldn't mind hurrying anyway...", completion = "My friend! I knew I could count on you. Please take these tokens for your effort.", objectives = "Collect 50 Valorstones while adventuring in Khaz Algar, Undermine, and K'aresh, then return to Cuzolth and upgrade a piece of Season 3 equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86364] = { id = 86364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crests from the Ether", description = "Wonderful. Valorstones are capable of upgrading lower-level equipment on their own. \n\nThat being said, Valorstones can only do so much. More powerful equipment will also require Ethereal Crests to upgrade to their full potential. These crests are rewarded through many different activities. Ethereal Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Weathered Ethereal Crests, and we can help you upgrade some gear further.", progress = "If you're having a hard time finding Weathered Ethereal Crests, you can search for hidden treasures around Khaz Algar, Undermine, or K'aresh. There's no shortage of those treasures!", completion = "This is wonderful. I'm excited for you to grow in power! And to advance my research, of course. But yes, your power growth!", objectives = "Acquire 15 Weathered Ethereal Crests by defeating unique creatures, conquering raids, completing world activities, or by looting caches. Then return to Vaskarn in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86365] = { id = 86365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crest Transmutation", description = "My friend, these Crests are magnificent. It looks like they can be transmuted into different tiers!\n\nIf you find yourself no longer in need of a lower-tier Crest, then I can transmute them to be more powerful. I can also transmute Crests into a weaker tier.\n\nLet's practice the transmutation process. Here's a few Carved Ethereal Crests. Speak to me and I can transform them into Weathered Ethereal Crests for you.", progress = "If you lose those Carved Ethereal Crests, you can find more from powerful creatures around K'aresh. I've heard there's quite a variety of them!", completion = "Remarkable!\n\nKeep in mind I can only transmute Crests into a higher tier when you have outgrown their usefulness, and it will be a costly process. Thank you for all of your help!", objectives = "Bring 15 Carved Ethereal Crests to Vaskarn in Dornogal, then trade them for a Pouch of Weathered Ethereal Crests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86367] = { id = 86367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grub Stompin'" }
quests[86369] = { id = 86369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sparkling Fortune", description = "You came right on time, {class}.\n\n<Custodian Khubon shows you a fractured crystal.>\n\nThis is a fractured spark of fortunes. Using a reagent like this on your gear will make the difference between great and magnificent.\n\nHowever, it is somewhat useless as it is nothing but a fragment. If you chance upon another in your adventures, bring it to me. Once you show me another, I will let you have this one so you can combine them into a spark of fortunes.", progress = "Were you able to find a fractured spark of fortunes? Is that a yes? No?", completion = "Excellent! Combine the two fractured sparks of fortunes to create a powerful spark of fortunes. You can always combine more using your own crafting efforts.", objectives = "Find another Fractured Spark of Fortunes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86372] = { id = 86372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasting the Wastelanders" }
quests[86388] = { id = 86388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spark - Template" }
quests[86390] = { id = 86390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggenfogger Nuisance" }
quests[86391] = { id = 86391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back our Power" }
quests[86392] = { id = 86392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foxy Footwork", description = "Your efforts in teaching the matriarch to hunt have been too effective, it seems. Several broker guards have been attacked recently. \n\nSince you caused this issue, I need you to solve it. Best the thorntail matriarch in a fight. The rest of the thorntails will back down once their leader is humbled.", progress = "Have you made a suitable display of dominance?", completion = "I knew you would be effective in this situation. I did not know it would be such a pleasure to watch you accomplish your task.", objectives = "Challenge and defeat the Thorntail Matriarch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86395] = { id = 86395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Stolen" }
quests[86396] = { id = 86396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Better Part of Valorstones", description = "Months into our stay in Dornogal and we're still learning about Valorstones! They seem to have limitless potential in empowering gear to its limits.\n\nBut I'm running low on research supplies. Could you bring me some? Cuzolth will be happy to help you upgrade some of your gear. He will. I'll make sure of it. <Vaskarn grins at Cuzolth.>", progress = "There's no need to hurry. But if you wouldn't mind hurrying anyway...", completion = "My friend! I knew I could count on you to bring me more Valorstones. Please take these tokens for your trouble.", objectives = "Collect 50 Valorstones while adventuring in Khaz Algar, then return to Cuzolth and upgrade a piece of Season 2 equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86399] = { id = 86399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Undermine the Crests", description = "As you can see, upgrading your lower-level equipment is easy and only requires Valorstones.\n\nHowever, Valorstones can only do so much. You'll also need Undermine Crests to develop your equipment to its peak for your upcoming adventures.\n\nThese Crests are rewarded through different activities. Undermine Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Weathered Undermine Crests, and we can help you upgrade some gear further.", progress = "If you're having a hard time finding Weathered Undermine Crests, you can search for hidden treasures around Khaz Algar or those underground areas, including Undermine. There's no shortage of those treasures!", completion = "This is wonderful. I'm excited for you to grow in power! And to advance my research, of course. But yes, your power growth!", objectives = "Acquire 15 Weathered Undermine Crests by defeating unique creatures, conquering raids, completing world activities, or by looting caches. Then return to Vaskarn in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86401] = { id = 86401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crest Transmutation", description = "My friend, these Crests are magnificent. Did you know you could transmute them into different tier of Crest? I have the tools here to do it... hang on... I know they're here.\n\nAh, yes. If you need to transmute your Crests to a lower tier, that's easy. I can do that for you. If you want to transmute them to be more powerful, you'll need to outgrow the lower tier of crest so you have no use for them anymore. I can convert them for you then, but it's costly.", progress = "If you lose those Carved Undermine Crests, you can find more from powerful creatures around Khaz Algar. I've heard there's quite a variety of them!", completion = "Remarkable, isn't it?\n\nI'm proud of how much I've learned about crests. Just two years ago, transmutation was a dream, and now it's almost my regular job. Well, a part of my regular job. Well, a part of my regular job when you need the help. Cuzolth and I really appreciate all the help you've given us.", objectives = "Bring 15 Carved Undermine Crests to Vaskarn in Dornogal, then trade them for a Pouch of Weathered Undermine Crests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86408] = { id = 86408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Hole in the Wall", description = "Never thought when I was lookin' for security I'd get some kinda bona fide hero. I can see why rumors about you spread so quickly. You like helpin' people, don'tcha?\n\nLook I don't wanna get all sappy or nothin'. It's just... What you did for everyone... \n\n<Mama Keara shakes her head and regains her composure.>\n\nAnyways. A deal's a deal. Sign your name on the apartment log over there and you'll be an official Barrelbottom resident. I'd say you've definitely earned it.", completion = "<With your name signed in the ledger, you gain full rights to the top floor of the Barrelbottom Apartments.>", objectives = "Inspect the Barrelbottom Apartment Log.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86409] = { id = 86409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalking the Crags" }
quests[86410] = { id = 86410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slime Wranglin'" }
