quests[86417] = { id = 86417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready Check", description = "We've done what we can here, {name}. Now we just have to hope it'll be enough.\n\nMaybe Gazlowe's got a plan. Maybe now we're ready to face down Gallywix. Let's formulate our next steps. I enjoy a bit of formulation from time to time.", completion = "I got a whole bunch of goblins who wanna have a word with management.", objectives = "Check in with Grimla about what to do next.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
