quests[86448] = { id = 86448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piecing Things Together", description = "<Elise Starseeker should be able to piece these Bounty's Remnants back together.>", objectives = "Purchase a Delver's Bounty from Elise Starseeker in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86456] = { id = 86456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Elegy for a Silent World", description = "<The crystal you are holding vibrates faintly in your hand. The energy it emits feels like it is holding your hand, trying to reach out and never let go--like it wants you to hold it, to bring it to safety. You can hear a faint song in the back of your mind--a song of fear, confusion, and longing for life.\n\nMaybe Ve'nari would know more about it?>", progress = "I am dealing with another crisis in my eco-domes, {name}. Make it quick or move aside.", completion = "<Ve'nari stops, as if distracted by a song.>\n\nWhere did you find this crystal? I can hear it, in my head, singing to me.", objectives = "Bring the Dimmed Crystal to Ve'nari in the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86457] = { id = 86457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lullaby of Hope", description = "{name}, do you know what this is?\n\nIf I am right, this crystal is the essence of my world, K'aresh. I've spent much of my capital preserving some bit of K'aresh through the eco-dome project. But this...\n\nI do not wish to assume anything before verifying if it is true.\n\nPlace down the shard, and let's see what we can find.", progress = "If this crystal is what I think it is, we have found a new hope of saving K'aresh.", completion = "I can't believe it! I...\n\n<Ve'nari's voice chokes.>\n\n{name}, what you have found is going to change the future of K'aresh.\n\nThe future of my people.", objectives = "Place the Dimmed Crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
